package com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.persistence;
import com.hrcoresystem.hrcore_api.modules.tenant.incidents.domain.model.IncidentModels.*; import jakarta.persistence.*; import java.time.*; import java.util.UUID; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="incident_actions") @Getter @Setter public class IncidentActionEntity { @Id UUID id; @Column(name="incident_id") UUID incidentId; @Enumerated(EnumType.STRING) @Column(name="action_type") ActionType actionType; @Column(columnDefinition="TEXT") String description; @Column(name="action_date") LocalDate actionDate; @Enumerated(EnumType.STRING) ActionStatus status; @Column(name="responsible_user_id") UUID responsibleUserId; Instant completedAt; @Column(columnDefinition="TEXT") String notes; Instant createdAt; Instant updatedAt; @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();} }
